/// v0.8.71 (Round B assoc): the HEIC family's index in `ASSOC_FAMILIES` — the ONE row whose Windows
/// availability is conditional (WIC decodes HEIC only through the installable HEVC/HEIF Image
/// Extensions; every other family decodes unconditionally). Pinned by `assoc_families_cover_…` so a
/// list reorder can't silently re-point the gate at another family.
pub(crate) const HEIC_FAMILY_IDX: usize = 3;

/// v0.9.16 (Round B assoc, Mac): Falcon's bundle identifier — MUST match scripts/mac-bundle.sh's
/// CFBundleIdentifier (pinned by `mac_plist_covers_assoc_families`). The LS default-handler calls
/// target this id; an unbundled dev binary isn't registered with LaunchServices, so "Make default"
/// only takes effect from the real .app (surfaced in the card copy).
#[cfg_attr(not(target_os = "macos"), allow(dead_code))] // Mac-only consumer; pinned by tests on every host
pub(crate) const FALCON_BUNDLE_ID: &str = "com.hwu0101.falcon";
/// Preview's bundle id — the owner-specified reset fallback when no incumbent was captured.
#[cfg_attr(not(target_os = "macos"), allow(dead_code))] // Mac-only consumer; pinned by tests on every host
pub(crate) const PREVIEW_BUNDLE_ID: &str = "com.apple.Preview";

/// v0.9.16 (Round B assoc, Mac): the "Reset to previous default" TARGET — pure over (captured
/// incumbent, the UTI's live handler list) so the owner's fallback ladder unit-tests on any host:
///   1. the captured incumbent, IF it still exists (present in LSCopyAllRoleHandlersForContentType);
///   2. else Preview, IF Preview is in that list;
///   3. else None → the button disables (the row note explains).
/// Falcon itself is never a valid reset target (resetting to Falcon would be a no-op lie).
#[cfg_attr(not(target_os = "macos"), allow(dead_code))] // Mac-only consumer; pinned by tests on every host
pub(crate) fn assoc_reset_target(prev: Option<&str>, all_handlers: &[String]) -> Option<String> {
    let eq = |a: &str, b: &str| a.eq_ignore_ascii_case(b); // LS bundle-id matching is case-insensitive
    if let Some(p) = prev {
        if !eq(p, FALCON_BUNDLE_ID) && all_handlers.iter().any(|h| eq(h, p)) {
            return Some(p.to_string());
        }
    }
    all_handlers.iter().find(|h| eq(h, PREVIEW_BUNDLE_ID)).cloned()
}

/// v0.9.16 (Round B assoc, Mac): the first-launch popup's choice → family-index set (ASSOC_FAMILIES
/// order). 0 = None (declare-only), 1 = RAW + JPG/HEIC (the photographer core: JPEG, HEIC, RAW),
/// 2 = all supported formats. Pure; pinned by test against the family labels.
#[cfg_attr(not(target_os = "macos"), allow(dead_code))] // Mac-only consumer; pinned by tests on every host
pub(crate) fn assoc_prompt_families(choice: i32) -> &'static [usize] {
    match choice {
        1 => &[0, HEIC_FAMILY_IDX, 8],
        2 => &[0, 1, 2, 3, 4, 5, 6, 7, 8],
        _ => &[],
    }
}

/// v0.8.71 (Round B assoc): whether the Settings HEIC association row is available on this platform.
/// Windows: the READ-ONLY WIC codec-registry probe (falcon-decode, session-cached — a codec installed
/// mid-session enables on the next launch, accepted). macOS/other: `true` — Image I/O decodes HEIC
/// natively, no probe (the accel_avail_for per-platform-availability rule: never gate one platform's
/// arm on another's probe).
pub(crate) fn heic_codec_present() -> bool {
    #[cfg(windows)]
    {
        falcon_decode::wic_heif_codec_present()
    }
    #[cfg(not(windows))]
    {
        true
    }
}

/// v0.8.71 (Round B assoc): force the HEIC family OFF in an apply-mask when the OS codec is absent —
/// registering an Open-With claim for a format the machine cannot decode would be a lie (Explorer
/// would offer Falcon, Falcon would show the decode-failure card). PURE so the gate unit-tests on any
/// host; the callers pass `heic_codec_present()`. Every other family passes through untouched.
pub(crate) fn gate_heic(on: &mut [bool], heic_avail: bool) {
    if !heic_avail {
        if let Some(h) = on.get_mut(HEIC_FAMILY_IDX) {
            *h = false;
        }
    }
}

